import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const vendor = resolve(root, 'src/vendor');
await mkdir(vendor, { recursive: true });
const script = (await readFile(resolve(root, 'node_modules/leaflet/dist/leaflet.js'), 'utf8')).replace(/\/\/# sourceMappingURL=.*$/m, '');
const style = await readFile(resolve(root, 'node_modules/leaflet/dist/leaflet.css'), 'utf8');
const license = await readFile(resolve(root, 'node_modules/leaflet/LICENSE'), 'utf8');
await writeFile(resolve(vendor, 'leaflet.ts'), '// Leaflet 1.9.4, BSD-2-Clause. Generated by npm run maps:bundle.\n// Local code only; tiles are fetched separately. See leaflet.LICENSE.txt.\nexport const leafletScript = ' + JSON.stringify(script) + ';\nexport const leafletStyle = ' + JSON.stringify(style) + ';\n');
await writeFile(resolve(vendor, 'leaflet.LICENSE.txt'), license);
console.log('Bundled Leaflet code, styles and license for native and browser maps.');
